INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38011, 'Amos 1:4', 'Amos', 1, 4, 'نو زه به په هغې ماڼۍ باندې اور نازل کړم چې حزاییل پاچا جوړه کړې ده او د بنهدد پاچا قوي کلاګانې به وسوځوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_4.mp3', '', 1761754199, 1761754199),
(38012, 'Amos 1:5', 'Amos', 1, 5, 'زه به د دمشق دروازې دړې وړې کړم او د آون د درې خلک به ووژنم او د بیت‌ عدن پاچا به له منځه یوسم. د سوریې خلک به د اسیرانو په توګه د قیر وطن ته بوتلل شي.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_5.mp3', '', 1761754199, 1761754199),
(38013, 'Amos 1:6', 'Amos', 1, 6, 'څښتن داسې وایي: «د غزې خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی د ټولو کلیو خلک په جلاوطنۍ بوتلل او د ادوم خلکو ته یې په لاس ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_6.mp3', '', 1761754199, 1761754199),
(38014, 'Amos 1:7', 'Amos', 1, 7, 'نو زه به د غزې د ښار په دېوالونو باندې اور نازل کړم او اور به د هغه قوي کلاګانې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_7.mp3', '', 1761754199, 1761754199),
(38015, 'Amos 1:8', 'Amos', 1, 8, 'زه به د اشدود خلک تباه کړم او د اشقلون د ښار پاچا به له منځه یوسم. زه به د عقرون ښار ته سزا ورکړم او کوم فلسطینیان چې پاتې دي، هغوی ټول به ووژل شي.» دا هغه څه دي چې څښتن تعالی ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_8.mp3', '', 1761754199, 1761754199),
(38016, 'Amos 1:9', 'Amos', 1, 9, 'څښتن داسې وایي: «د صور د ښار خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی د ټولو کليو خلک بوتلل او د ادوم خلکو ته یې په لاس ورکړل او هغوی چې د ورورګلوۍ کوم تړون کړی ؤ، هغه یې مات کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_9.mp3', '', 1761754199, 1761754199),
(38017, 'Amos 1:10', 'Amos', 1, 10, 'نو زه به د صور د ښار په دېوالونو باندې اور نازل کړم او اور به د هغه قوي کلاګانې وسوځوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_10.mp3', '', 1761754199, 1761754199),
(38018, 'Amos 1:11', 'Amos', 1, 11, 'څښتن داسې وایي: «د ادوم خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی خپلو خپلوانو یعنې اسراییلیانو پسې توره راخیستې ده او په هغوی باندې یې هېڅ رحم نه دی کړی. د هغوی قهر او غضب بې‌حده ؤ او هېڅ نه سړېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_11.mp3', '', 1761754199, 1761754199),
(38019, 'Amos 1:12', 'Amos', 1, 12, 'نو زه به د تیمان په ښار باندې اور نازل کړم او د بصرې قوي کلاګانې به وسوځوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_12.mp3', '', 1761754199, 1761754199),
(38020, 'Amos 1:13', 'Amos', 1, 13, 'څښتن داسې وایي: «د عمون خلکو په پرله پسې توګه ګناه کړې ده، نو له دې امله به زه هغوی ته خامخا سزا ورکړم. هغوی په جلعاد کې د زیاتې سیمې د نیولو په خاطر د امیدوارو ښځو خېټې وشکولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_13.mp3', '', 1761754199, 1761754199),
(38021, 'Amos 1:14', 'Amos', 1, 14, 'نو زه به د ربه د ښار په دېوالونو باندې اور واچوم او د هغه قوي کلاګانې به وسوځوم، نو په هغه ورځ به هلته د جنګ چیغې جوړې شي او جنګ به لکه د توفان په شان راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_14.mp3', '', 1761754199, 1761754199),
(38022, 'Amos 1:15', 'Amos', 1, 15, 'او د هغه پاچا به د خپلو مامورانو سره جلاوطنه شي.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos1_verse_15.mp3', '', 1761754199, 1761754199),
(38023, 'Joel 2:1', 'Joel', 2, 1, 'په صيون کښې بيګل وغږوئ، او زما په مقدس غرۀ د جنګ اعلان وکړئ. او د دې مُلک اوسېدونکى دې ټول د يرې نه ولړزيږى، ځکه چې د مالِک خُدائ د قيامت ورځ راتلونکى ده، بلکې نزدې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_1.mp3', '', 1761754199, 1761754199),
(38024, 'Joel 2:2', 'Joel', 2, 2, 'دا د تورې تيارې او غم ورځ ده، د ګڼو وريځو او تورو تيارو يوه ورځ ده. لکه څنګه چې د سحر رڼا په غرونو راخوريږى داسې يو لوئ او طاقتور لښکر راروان دے، چې داسې به نۀ پخوا چا ليدلے وى او نۀ به په راتلونکى وخت کښې کله راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_2.mp3', '', 1761754199, 1761754199),
(38025, 'Joel 2:3', 'Joel', 2, 3, 'د هغوئ نه وړاندې اور هر څۀ سوزوى، او د هغوئ شاته د اور لمبې روانې وى. د هغوئ په وړاندې مُلک لکه د باغِ عدن په شان ښکلے پروت دے. خو د هغوئ نه وروستو زمکه لکه د صحرا په شان شى او د هغوئ نه هيڅ شے بچ نۀ پاتې کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_3.mp3', '', 1761754199, 1761754199),
(38026, 'Joel 2:4', 'Joel', 2, 4, 'هغوئ په ليدلو کښې د آسونو په شان ښکارى، او هغوئ د جنګى آسونو په شان منډې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_4.mp3', '', 1761754199, 1761754199),
(38027, 'Joel 2:5', 'Joel', 2, 5, 'د جنګى ګاډو د شور په شان هغوئ د غرونو په څوکو په ټوپونو تېريږى، او داسې ټسار کوى لکه کله چې اور ګياه سوزوى او يا لکه چې طاقتور فوج جنګ ته روان وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_5.mp3', '', 1761754199, 1761754199),
(38028, 'Joel 2:6', 'Joel', 2, 6, 'د هغوئ په نظر کښې قومونه يره کښې دى، او د هر چا مخ د يرې نه زېړ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_6.mp3', '', 1761754199, 1761754199),
(38029, 'Joel 2:7', 'Joel', 2, 7, 'هغوئ لکه د جنګيالو په شان حمله کوى، او د فوجيانو په شان په دېوالونو ورخېژى. هغوئ ټول په قطار کښې سيدها ځى، او د خپلې لارې نه اخوا ديخوا نۀ اوړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_7.mp3', '', 1761754199, 1761754199),
(38030, 'Joel 2:8', 'Joel', 2, 8, 'هغوئ يو بل له ديکې نۀ ورکوى، هر يو په خپله لاره نېغ ځى. او هغوئ د صفونو په صورت کښې د دشمن په مورچو ورننوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_8.mp3', '', 1761754199, 1761754199),
(38031, 'Joel 2:9', 'Joel', 2, 9, 'هغوئ په ښار باندې حملې دپاره ورغر وهى، او په دېوالونو يې په منډه وراوړى. هغوئ کورونو ته وراوړى او په کړکيانو باندې لکه د غلو په شان ورننوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_9.mp3', '', 1761754199, 1761754199),
(38032, 'Joel 2:10', 'Joel', 2, 10, 'هغوئ چې وړاندې ځى زمکه خوځيږى، آسمان لړزيږى، نمر او سپوږمۍ تيارۀ شى، او ستورى نور نۀ ‎ځليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_10.mp3', '', 1761754199, 1761754199),
(38033, 'Joel 2:11', 'Joel', 2, 11, 'مالِک خُدائ د خپل لښکر نه وړاندې لکه د تندر ګړزيږى. د هغۀ لښکر د شمېر نه بهر دے، او هغوئ طاقتور دى څوک چې د هغۀ حکم منى. د مالِک خُدائ د قيامت ورځ عظيمه، او سخته يروونکى ده. څوک دا برداشت کولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_11.mp3', '', 1761754199, 1761754199),
(38034, 'Joel 2:12', 'Joel', 2, 12, 'مالِک خُدائ فرمائى چې، ”اوس هم تاسو سره موقع شته چې خپل ټول زړۀ سره ما ته په روژه نيولو، په ژړا او ماتم کولو سره راوګرځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_12.mp3', '', 1761754199, 1761754199),
(38035, 'Joel 2:13', 'Joel', 2, 13, 'د خپل خفګان دپاره خپلې جامې مۀ شلوئ خو د هغې په ځائ خپل زړونه وشلوئ.“ مالِک خُدائ خپل خُدائ پاک ته راوګرځئ، ځکه چې هغه رحمان او رحيم دے، هغه زر نۀ غصه کيږى او د هغۀ مينه نۀ ختمېدونکى ده، او هغه دا غواړى چې معافى وکړى او سزا ورنۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_13.mp3', '', 1761754199, 1761754199),
(38036, 'Joel 2:14', 'Joel', 2, 14, 'چا ته پته ده، کېدے شى چې هغه بدل شى او زړۀ يې نرم شى او د لعنت په ځائ برکت درکړى. او تاسو لکه د مخکښې په شان د غلې او د ميو نذرانې مالِک خُدائ خپل خُدائ پاک ته پېش کړے شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_14.mp3', '', 1761754199, 1761754199),
(38037, 'Joel 2:15', 'Joel', 2, 15, 'په صيون کښې بيګل وغږوئ، د مقدسې روژې اعلان وکړئ، او خلق مقدسې اجتماع له راوغواړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_15.mp3', '', 1761754199, 1761754199),
(38038, 'Joel 2:16', 'Joel', 2, 16, 'ټول خلق راغونډ کړئ، او غونډه مقدسه کړئ، مشران، ماشومان او واړۀ ماشومان راغونډ کړئ. ناوې او زلمے د خپلې خپلې کوټې نه راوغواړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_16.mp3', '', 1761754199, 1761754199),
(38039, 'Joel 2:17', 'Joel', 2, 17, 'هغه اِمامان چې د مالِک خُدائ په حضور کښې خِدمت کوى، هغوئ دې د خُدائ پاک د کور د ډيوډۍ او د قربان‌ګاه په مينځ کښې ودريږى او ژړا دې وکړى. هغوئ دې داسې دُعا وغواړى، ”اے مالِکه خُدايه خپل خلق بچ کړه. خپل خاص ميراث مۀ د خندا کوه. هغوئ مۀ پرېږده چې بې‌ايمانه غېر مُلکيان ورپورې ټوقې وکړى څوک چې دا وائى، د بنى اِسرائيلو خُدائ پاک هغوئ پرېښودى دى څۀ؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_17.mp3', '', 1761754199, 1761754199),
(38040, 'Joel 2:18', 'Joel', 2, 18, 'نو بيا به مالِک خُدائ په خپل مُلک غېرت وکړى، او په خپلو خلقو باندې به مهربان شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_18.mp3', '', 1761754199, 1761754199),
(38041, 'Joel 2:19', 'Joel', 2, 19, 'مالِک خُدائ به هغوئ ته جواب ورکړى چې، ”ګورئ، زۀ تاسو له دومره غله دانه، نوى مے او د زيتُونو تېل درکوم چې ښۀ ډېر وى او پرې ماړۀ شئ، زۀ به بيا هيڅکله تاسو د نورو قومونو د خندا نۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_19.mp3', '', 1761754199, 1761754199),
(38042, 'Joel 2:20', 'Joel', 2, 20, 'زۀ به ستاسو نه د شمال ټول فوجيان لرې وشړم، او هغوئ به زۀ خوشى صحرا او وران مُلک ته وشړم. او د هغوئ وړومبۍ دستې به مشرقى سمندر ته او وروستۍ به يې مغربى سمندر ته وغورزوم. او د هغوئ سخا شوى لاشونو نه به بدبوئ خېژى او په هر طرف به خوريږى. يقيناً چې مالِک خُدائ غټ کارونه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_20.mp3', '', 1761754199, 1761754199),
(38043, 'Joel 2:21', 'Joel', 2, 21, 'اے زمکې، مۀ يرېږه، خوشحالى وکړه او خوشحاله اوسه، يقيناً چې مالِک خُدائ غټ کارونه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_21.mp3', '', 1761754199, 1761754199),
(38044, 'Joel 2:22', 'Joel', 2, 22, 'اے ځنګلى ځناورو، مۀ يرېږئ. ځکه چې د صحرا د څرن زمکه راشنه کيږى. ونې به دوباره د مېوو نه ډکې شى، بيا به د اينځرو او د انګورو بوټى ښۀ ډېر ډک شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_22.mp3', '', 1761754199, 1761754199),
(38045, 'Joel 2:23', 'Joel', 2, 23, 'اے د يروشلم خلقو خوشحالى وکړئ. په مالِک خُدائ خپل خُدائ پاک کښې خوشحالى وکړئ. ځکه چې هغۀ په وفادارۍ سره په تاسو د خزان بارانونه وکړل. هغه په تاسو د مخکښې په شان د خزان او د سپرلى دواړو ډېر بارانونه راوروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_23.mp3', '', 1761754199, 1761754199),
(38046, 'Joel 2:24', 'Joel', 2, 24, 'درمندونه به بيا د غلې نه ډک شى، او چاټۍ به د نوؤ ميو او د زيتُونو د تېلو نه تر خولې خولې پورې ډکې شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_24.mp3', '', 1761754199, 1761754199),
(38047, 'Joel 2:25', 'Joel', 2, 25, 'مالِک خُدائ فرمائى چې، ”زۀ به تاسو ته د نقصان شوى فصل تاوان درکړم کوم چې د قحطۍ مُلخانو، غټو مُلخانو، وړو مُلخانو او نورو مُلخانو خوړلى وُو. دا زما لوئ لښکر وو چې ستاسو خلاف مې درلېږلے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_25.mp3', '', 1761754199, 1761754199),
(38048, 'Joel 2:26', 'Joel', 2, 26, 'تاسو سره به د خوړلو دپاره هر څۀ ډېر تېر وى ترڅو چې تاسو ښۀ ماړۀ شئ، او تاسو به د مالِک خُدائ خپل خُدائ پاک د نوم شُکر ګزارى وکړئ، چا چې ستاسو دپاره معجزې کړې دى. نو بيا به هيڅکله زما خلق ونۀ شرميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_26.mp3', '', 1761754199, 1761754199),
(38049, 'Joel 2:27', 'Joel', 2, 27, 'نو بيا به تاسو پوهه شئ چې زۀ د خپلو خلقو بنى اِسرائيلو په مينځ کښې يم، او دا چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم او زما نه بغېر بل څوک نشته. نو بيا به هيڅکله زما خلق ونۀ شرميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_27.mp3', '', 1761754199, 1761754199),
(38050, 'Joel 2:28', 'Joel', 2, 28, 'د دې ټولو کارونو کولو نه وروستو به زۀ خپل روح په ټولو خلقو نازل کړم. ستاسو زامن او لوڼه به نبوت کوى، ستا مشران به خوبونه وينى، او ستاسو ځوانان به رويا ګانې وينى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_28.mp3', '', 1761754199, 1761754199),
(38051, 'Joel 2:29', 'Joel', 2, 29, 'په دې ورځو کښې به زۀ هم په نوکرانو سړو او ښځو دواړو خپل روح نازل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_29.mp3', '', 1761754199, 1761754199),
(38052, 'Joel 2:30', 'Joel', 2, 30, 'زۀ به په آسمانونو او زمکه کښې حېرانونکى نښې يعنې وينه، اور او د لوګى برجۍ ښکاره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_30.mp3', '', 1761754199, 1761754199),
(38053, 'Joel 2:31', 'Joel', 2, 31, 'نمر به تور شى، او سپوږمۍ به لکه د وينو تکه سره شى مخکښې د دې نه چې د مالِک خُدائ د قيامت هغه لويه او هيبتناکه ورځ راورسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_31.mp3', '', 1761754199, 1761754199),
(38054, 'Joel 2:32', 'Joel', 2, 32, 'خو هر څوک چې د مالِک خُدائ په نوم مدد وغواړى هغه به بچ شى. او څۀ به په يروشلم کښې د صيون د غرۀ نه وتښتى، لکه څنګه چې مالِک خُدائ فرمائيلى دى، او هغوئ به په بچ شوو کسانو کښې وى څوک چې مالِک خُدائ راغوښتى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joel2_verse_32.mp3', '', 1761754199, 1761754199),
(38055, 'Genesis 39:1', 'Genesis', 39, 1, 'اسماعیلیانو یوسف مصر ته یووړ او په فوطیفار باندې یې خرڅ کړ چې نوموړی د فرعون د درباریانو څخه ؤ او د دربار د ساتونکو قوماندان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_1.mp3', '', 1761754199, 1761754199),
(38056, 'Genesis 39:2', 'Genesis', 39, 2, 'څښتن د یوسف سره مل ؤ او هغه یې بریالی کړ. هغه د خپل مصري بادار په کور کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_2.mp3', '', 1761754199, 1761754199),
(38057, 'Genesis 39:3', 'Genesis', 39, 3, 'بادار یې ولیدل چې څښتن د یوسف سره مل دی او په هر کار کې هغه ته بری ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_3.mp3', '', 1761754199, 1761754199),
(38058, 'Genesis 39:4', 'Genesis', 39, 4, 'فوطیفار د هغه څخه خوشحاله ؤ او هغه یې خپل شخصي نوکر ونیوه او هرڅه یې چې خپل کور کې درلودل، ټول یې هغه ته وسپارل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_4.mp3', '', 1761754199, 1761754199),
(38059, 'Genesis 39:5', 'Genesis', 39, 5, 'د هماغه وخت څخه څښتن د یوسف له سببه د دې مصري خاندان ته برکت ورکړ او د هغه په ټولو شیانو باندې که د هغه په کور کې وو او که د هغه ځمکه وه، د څښتن برکت ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_5.mp3', '', 1761754199, 1761754199),
(38060, 'Genesis 39:6', 'Genesis', 39, 6, 'فوطیفار چې هرڅه درلودل هغه یې یوسف ته وسپارل چې څارنه یې وکړي. هغه له خوراک څخه پرته نور د هېڅ شي سره کار نه درلود. یوسف ډېر ښایسته ؤ او ښکلی اندام یې درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_6.mp3', '', 1761754199, 1761754199),
(38061, 'Genesis 39:7', 'Genesis', 39, 7, 'څه موده وروسته د یوسف سره د فوطیفار د ښځې مینه پیدا شوه او ورته ویې ویل: «راشه، زما سره څمله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_7.mp3', '', 1761754199, 1761754199),
(38062, 'Genesis 39:8', 'Genesis', 39, 8, 'خو هغه انکار وکړ او هغې ته یې وویل: «ګوره، هرڅه چې زما د بادار په کور کې دي د هغو په اړه هغه اندېښنه نه لري، ځکه چې زه دلته یم. هرڅه چې هغه یې لري ماته یې راسپارلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_8.mp3', '', 1761754199, 1761754199),
(38063, 'Genesis 39:9', 'Genesis', 39, 9, 'زه په دې کور کې داسې اختیار لرم لکه څنګه چې هغه یې لري او زما بادار پرته له ستا چې د هغه ښځه یې، نور هېڅ شی زما څخه نه دی سپمولی. نو بیا زه څنګه کولای شم چې داسې بد کار وکړم او د خدای په وړاندې ګناه وکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_9.mp3', '', 1761754199, 1761754199),
(38064, 'Genesis 39:10', 'Genesis', 39, 10, 'که څه هم هغې به هره ورځ ټینګار کاوه، خو یوسف د هغې خبرې نه منله چې ورسره څملي یا ورنژدې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_10.mp3', '', 1761754199, 1761754199),
(38065, 'Genesis 39:11', 'Genesis', 39, 11, 'خو یوه ورځ کله چې یوسف کور ته ننوت چې خپل کار وکړي، د کور د نوکرانو له جملې څخه هلته هېڅ څوک نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_11.mp3', '', 1761754199, 1761754199),
(38066, 'Genesis 39:12', 'Genesis', 39, 12, 'هغې یوسف له چپنې څخه ونیوه او ورته ویې ویل: «زما سره څمله.» خو هغه خپله چپنه د هغې په لاس کې پرېښودله او د کور څخه دباندې وتښتېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_12.mp3', '', 1761754199, 1761754199),
(38067, 'Genesis 39:13', 'Genesis', 39, 13, 'کله چې هغې ولیدل چې هغه خپله چپنه د هغې په لاس کې پرېښودله او د کور څخه وتښتېد،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_13.mp3', '', 1761754199, 1761754199),
(38068, 'Genesis 39:14', 'Genesis', 39, 14, 'نو د خپل کور نوکرانو ته یې غږ وکړ او ویې ویل: «وګورئ! دغه عبرانی سړی چې زما مېړه کور ته راوستلی دی، غواړي زمونږ بې‌عزتي وکړي. هغه زما کوټې ته راننوت چې ماته لاس راواچوي، خو ما په لوړ اواز سره چیغې ووهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_14.mp3', '', 1761754199, 1761754199),
(38069, 'Genesis 39:15', 'Genesis', 39, 15, 'کله چې هغه زما چیغې واورېدلې، نو وتښتېد او خپله چپنه یې زما سره پرېښودله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_15.mp3', '', 1761754199, 1761754199),
(38070, 'Genesis 39:16', 'Genesis', 39, 16, 'هغې د یوسف چپنه د ځان سره وساتله، تر هغې پورې چې مېړه یې کور ته راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_16.mp3', '', 1761754199, 1761754199),
(38071, 'Genesis 39:17', 'Genesis', 39, 17, 'بیا هغې فوطیفار ته دا کیسه بیان کړه: «هغه عبرانی غلام چې مونږ ته دې راوستلی دی، زما کوټې ته راننوت چې ما بې‌عزته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_17.mp3', '', 1761754199, 1761754199),
(38072, 'Genesis 39:18', 'Genesis', 39, 18, 'خو څنګه چې ما د مرستې دپاره چیغې ووهلې، خپله چپنه یې زما سره پرېښودله او د کور څخه وتښتېد.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_18.mp3', '', 1761754199, 1761754199),
(38073, 'Genesis 39:19', 'Genesis', 39, 19, 'کله چې د یوسف بادار دغه کیسه واورېدله چې د هغه ښځې ورته بیان کړه، هغه د قهره سور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_19.mp3', '', 1761754199, 1761754199),
(38074, 'Genesis 39:20', 'Genesis', 39, 20, 'د یوسف بادار هغه ونیوه او په هغه زندان کې یې واچاوه چې د پاچا بندیان به په کې ساتل کېدل او هغه هلته پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_20.mp3', '', 1761754199, 1761754199),
(38075, 'Genesis 39:21', 'Genesis', 39, 21, 'خو څښتن د یوسف سره مل ؤ. هغه ته یې برکت ورکړ، نو د زندان مشر د هغه څخه خوشحاله ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_21.mp3', '', 1761754199, 1761754199),
(38076, 'Genesis 39:22', 'Genesis', 39, 22, 'هغه یوسف د نورو ټولو بندیانو مشر وټاکه او هغه ته یې د هغو ټولو کارونو مسوولیت ور په غاړه کړ چې په زندان کې به کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_22.mp3', '', 1761754199, 1761754199),
(38077, 'Genesis 39:23', 'Genesis', 39, 23, 'د زندان مشر د هغو شیانو په هکله چې یوسف ته سپارل شوي وو اندېښنه نه درلودله، ځکه چې څښتن د یوسف سره مل ؤ او کوم کارونه چې هغه کول څښتن ورته په هغو ټولو کې بری ورکاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis39_verse_23.mp3', '', 1761754199, 1761754199),
(38078, 'Isaiah 59:1', 'Isaiah', 59, 1, 'ګومان مه کوئ چې د څښتن لاس دومره لنډ دی چې تاسو ژغورلی نه شي او یا یې غوږ دومره دروند دی چې ستاسو زارۍ اورېدلی نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_1.mp3', '', 1761754199, 1761754199),
(38079, 'Isaiah 59:2', 'Isaiah', 59, 2, 'خو پوه شئ چې ستاسو بد عمل ستاسو او د څښتن ترمنځ بېلتون راوستی دی. ستاسو ګناهونو د هغه مخ ستاسو څخه پټ کړی دی، له دې کبله هغه ستاسو زارۍ نه اوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_2.mp3', '', 1761754199, 1761754199),
(38080, 'Isaiah 59:3', 'Isaiah', 59, 3, 'لاسونه مو په وینو او ګوتې مو په ګناه ککړې دي. له شونډو نه مو دروغ راوځي او ژبه مو په بدو خبرو خوځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_3.mp3', '', 1761754199, 1761754199),
(38081, 'Isaiah 59:4', 'Isaiah', 59, 4, 'هېڅوک په محکمه کې له انصافه کار نه اخلي او رښتینی قضاوت نه کوي. په دروغو تکیه کوي چې خپله دعوه وګټي او نورو ته د نقصان رسولو نقشې جوړوي او بدي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_4.mp3', '', 1761754199, 1761754199),
(38082, 'Isaiah 59:5', 'Isaiah', 59, 5, 'د هغوی نقشې د مار د هګیو په شان دي چې کله ماتې شي، نو د خلکو د تباهۍ دپاره کارول کیږي. خو دا نقشې هم د غڼو د جالونو په شان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_5.mp3', '', 1761754199, 1761754199),
(38083, 'Isaiah 59:6', 'Isaiah', 59, 6, 'هغوی نه شي کولای چې د غڼو د تارونو څخه کالي جوړ کړي، ترڅو خپل ځانونه ورباندې پټ کړي. هر ډول بد عملونه د هغوی له خوا رامنځته کیږي او لاسونه یې د خلکو د تباه کولو دپاره تیار دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_6.mp3', '', 1761754199, 1761754199),
(38084, 'Isaiah 59:7', 'Isaiah', 59, 7, 'هغوی ګناه کولو دپاره منډې وهي او زر زر د بې ګناه خلکو وینه تویوي. دوی یوازې د بدۍ نقشې جوړوي او د ژوند لاره یې ورانی او تباهي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_7.mp3', '', 1761754199, 1761754199),
(38085, 'Isaiah 59:8', 'Isaiah', 59, 8, 'هغوی د سولې او سلامتۍ لاره نه پېژني او د هغوی په لارو کې انصاف نشته. هغوی په کږو لارو باندې روان دي. هرڅوک چې په داسې لارو باندې ځي، سوله او سلامتي نه پېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_8.mp3', '', 1761754199, 1761754199),
(38086, 'Isaiah 59:9', 'Isaiah', 59, 9, 'خلک وایي: «اوس مونږ پوهېږو چې ولې زمونږ سره انصاف نه کیږي او خدای ولې مونږ د هغو خلکو نه چې په مونږ ظلم کوي، نه ژغوري. مونږ د رڼا په هیله یو. خو ګورئ، مونږ ته یوازې تیاره ښکاري، رڼا نه وینو او په تیاره کې روان یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_9.mp3', '', 1761754199, 1761754199),
(38087, 'Isaiah 59:10', 'Isaiah', 59, 10, 'مونږ د ړندو خلکو په شان په تیاره کې لاس په دېوال کېږدو او روانېږو. مونږ په رڼا ورځ لکه د شپې په شان تیندکونه خورو او په ژوندیو خلکو کې د مړو په شان یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_10.mp3', '', 1761754199, 1761754199),
(38088, 'Isaiah 59:11', 'Isaiah', 59, 11, 'مونږ ټول لکه د اېږو په شان غورېږو او د کوترو په شان سخت زګېروي کوو. د انصاف په تمه یو، خو هغه نشته. د ژغورنې په هیله یو، خو ژغورنه زمونږ نه ډېره لېرې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_11.mp3', '', 1761754199, 1761754199),
(38089, 'Isaiah 59:12', 'Isaiah', 59, 12, 'ځکه مونږ ستا په وړاندې ډېر جرمونه کړي دي او ګناهونه مو زمونږ په ضد شاهدي ورکوي. مونږ مجرمان یو او خپل ګناهونه منو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_12.mp3', '', 1761754199, 1761754199),
(38090, 'Isaiah 59:13', 'Isaiah', 59, 13, 'مونږ ستا په وړاندې بغاوت کړی دی. ته مو نه یې منلی او ستا له پیروۍ نه مو انکار کړی دی. مونږ په نورو ظلم او سرغړونه کړې ده. زمونږ خیالونه سم نه دي او زمونږ خبرې دروغ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_13.mp3', '', 1761754199, 1761754199),
(38091, 'Isaiah 59:14', 'Isaiah', 59, 14, 'انصاف مو پریښی دی او عدالت زمونږ نه لېرې ولاړ دی. رښتیا په کوڅه او بازار کې تیندک خوړلی دی او رښتینولي هلته هېڅ ځای نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_14.mp3', '', 1761754199, 1761754199),
(38092, 'Isaiah 59:15', 'Isaiah', 59, 15, 'هېڅوک رښتیا نه وایي او څوک چې غواړي له بدۍ نه لاس واخلی، په هغه باندې حمله کیږي.» څښتن دا هرڅه ولیدل او هغه په دې خفه ؤ چې انصاف نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_15.mp3', '', 1761754199, 1761754199),
(38093, 'Isaiah 59:16', 'Isaiah', 59, 16, 'هغه هک پک حیران پاتې شو چې داسې هېڅوک نشته چې د مظلومانو سره مرسته وکړي. نو هغه د خپلو قوي مټو څخه کار واخيست چې هغوی وژغوري. د څښتن عدالت هغه بریالی کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_16.mp3', '', 1761754199, 1761754199),
(38094, 'Isaiah 59:17', 'Isaiah', 59, 17, 'هغه عدالت د زغرو د کالیو په شان واغوست او د خلاصون د زغرو خولۍ یې په سر کړه. هغه د بدل اخیستلو کالي واغوستل او د غیرت چپنه یې په تن کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_17.mp3', '', 1761754199, 1761754199),
(38095, 'Isaiah 59:18', 'Isaiah', 59, 18, 'هغه به خپلو دښمنانو ته د هغوی د کړنو سره سم سزا ورکړي او غضب به یې ور باندې نازل شي، حتی که هغوی په ډېرو لېرې هېوادونو کې هم واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_18.mp3', '', 1761754199, 1761754199),
(38096, 'Isaiah 59:19', 'Isaiah', 59, 19, 'نو هغه وخت به د لوېدیځ خلک د څښتن د نوم څخه ووېریږي او څوک چې په ختیځ کې اوسیږي هغوی به د څښتن د جلال په لیدلو سره وډار شي. ځکه چې هغه به د یو تېز سیلاب په شان په هغوی باندې راشي لکه د څښتن باد چې هغه راروان کړی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_19.mp3', '', 1761754199, 1761754199),
(38097, 'Isaiah 59:20', 'Isaiah', 59, 20, 'څښتن خپل قوم ته داسې وایي: «یو خلاصوونکی به صهیون ته راشي، ترڅو د یعقوب له اولادې څخه هغه کسان چې د خپلو ګناهونو نه توبه وباسي، وژغوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_20.mp3', '', 1761754199, 1761754199),
(38098, 'Isaiah 59:21', 'Isaiah', 59, 21, 'څښتن وایي: «زه ستاسو سره دا لوظ کوم: ‹زه تاسو ته خپل روح درکوم او خپل کلام مې په تاسو باندې نازل کړی دی. دا خبرې به نه ستاسو، نه ستاسو د ماشومانو او نه ستاسو د لمسیانو له خولې څخه لېرې شي. دا زما وعده ده، له همدا اوس نه تر ابده پورې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah59_verse_21.mp3', '', 1761754199, 1761754199),
(38099, 'Psalms 2:1', 'Psalms', 2, 1, 'ولې په قهر شول نور قومونه دومره؟ ولې بېځایه دسیسې جوړوي دغه قومونه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_1.mp3', '', 1761754199, 1761754199),
(38100, 'Psalms 2:2', 'Psalms', 2, 2, 'تیاروي ځانونه جنګ ته پاچاهان د جهان دي لګیا حکمرانان د دسیسو په جوړولو یو له بله سره د څښتن او د هغه د غوره شوي پاچا په وړاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_2.mp3', '', 1761754199, 1761754199),
(38101, 'Psalms 2:3', 'Psalms', 2, 3, 'وایي: «راځئ چې زنځیرونه مات کړو د غلامۍ رسۍ به وغورځوو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_3.mp3', '', 1761754199, 1761754199),
(38102, 'Psalms 2:4', 'Psalms', 2, 4, 'څښتن چې ناست دی په اسمان کې په خپل تخت باندې خاندي ملنډې وهي په پلانونو د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_4.mp3', '', 1761754199, 1761754199),
(38103, 'Psalms 2:5', 'Psalms', 2, 5, 'ورکوي دوی ته په خپل قهر اخطار وېروي دوی په خپل غضب باندې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_5.mp3', '', 1761754199, 1761754199),
(38104, 'Psalms 2:6', 'Psalms', 2, 6, '«ما مقرر کړ خپل پاچا په خپله پاکه غونډۍ نوم دی صهیون د غونډۍ»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_6.mp3', '', 1761754199, 1761754199),
(38105, 'Psalms 2:7', 'Psalms', 2, 7, 'پاچا وایي: «زه به اعلان کړم د څښتن فرمان ماته وویل هغه چې ته مې زوی زه دې نن پلار شوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_7.mp3', '', 1761754199, 1761754199),
(38106, 'Psalms 2:8', 'Psalms', 2, 8, 'سوال وکړه له ما نه ته ټول قومونه در به کړم نړۍ ټوله به د ستا شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_8.mp3', '', 1761754199, 1761754199),
(38107, 'Psalms 2:9', 'Psalms', 2, 9, 'هغوی به مات کړې د اوسپنې امسا باندې د خاورینو لوښو په شان به کړې دوی سم ټوټې ټوټې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_9.mp3', '', 1761754199, 1761754199),
(38108, 'Psalms 2:10', 'Psalms', 2, 10, 'شئ هوښیار ای پاچاهانو تاسو دې نه عبرت واخلئ د نړۍ حکمرانانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_10.mp3', '', 1761754199, 1761754199),
(38109, 'Psalms 2:11', 'Psalms', 2, 11, 'د څښتن عبادت وکړئ ښه په وېره او لړزان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_11.mp3', '', 1761754199, 1761754199),
(38110, 'Psalms 2:12', 'Psalms', 2, 12, 'زوی ته یې ټیټ کړئ د درناوي سرونه هسې نه چې دی په قهر شي زر او خپلو لارو کې هلاک شئ هرڅوک چې پناه وروړي بختور دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms2_verse_12.mp3', '', 1761754199, 1761754199);